// Station 1.4: Dieselbe Taxizentrale – jetzt als Kompositum.
// Die Liste endet nicht mehr mit null, sondern mit einem Abschluss-Objekt.

Liste imDienst = new Liste();
println("Leere Liste, Länge: " + imDienst.laenge());

imDienst.add(new Taxi(12, "Stefan"));
imDienst.add(new Taxi(7, "Aylin"));
imDienst.add(new Taxi(3, "Jonas"));
imDienst.add(new Taxi(21, "Mira"));

println("Im Dienst:");
imDienst.ausgeben();
println("Anzahl: " + imDienst.laenge());
println("Ist Taxi 7 im Dienst? " + imDienst.enthaelt(new Taxi(7, "Aylin")));

println("Taxi 12 und Taxi 21 melden sich ab.");
imDienst.entfernen(new Taxi(12, "Stefan"));
imDienst.entfernen(new Taxi(21, "Mira"));
imDienst.ausgeben();
println("Anzahl: " + imDienst.laenge());

/**
 * Die Liste als Kompositum: anfang ist nie null. In der leeren Liste
 * zeigt anfang auf den Abschluss.
 */
public class Liste {
   private ListenElement anfang;

   public Liste() {
      anfang = new Abschluss();
   }

   public boolean isEmpty() {
      return anfang.laenge() == 0;
   }

   public int laenge() {
      return anfang.laenge();
   }

   public boolean enthaelt(DatenElement d) {
      return anfang.enthaelt(d);
   }

   public boolean add(DatenElement d) {
      // TODO 4c (Aufgabe 4): anfang.add(d) aufrufen – und das Ergebnis?
      return true;
   }

   public boolean entfernen(DatenElement d) {
      if (enthaelt(d)) {
         anfang = anfang.entfernen(d);
         return true;
      } else {
         return false;
      }
   }

   public void ausgeben() {
      anfang.ausgeben();
   }

   // Hilfsmethode für die Tests
   public String alsText() {
      return anfang.alsText();
   }
}

/**
 * Gemeinsamer Typ von Knoten und Abschluss (Entwurfsmuster Kompositum).
 * Abstrakte Klasse: Von ihr selbst gibt es keine Objekte. Jede Unterklasse
 * muss alle abstrakten Methoden auf ihre eigene Weise umsetzen.
 */
public abstract class ListenElement {

   // Anzahl der Knoten ab hier
   public abstract int laenge();

   // Ist d ab hier enthalten?
   public abstract boolean enthaelt(DatenElement d);

   // Hängt d am Ende an. Rückgabe: das Element, das jetzt an dieser Stelle steht.
   public abstract ListenElement add(DatenElement d);

   // Entfernt den ersten Knoten mit d. Rückgabe: das Element, das jetzt an dieser Stelle steht.
   public abstract ListenElement entfernen(DatenElement d);

   public abstract void ausgeben();

   public abstract String alsText();
}

/**
 * Ein Knoten der Liste. Sein Nachfolger ist ein ListenElement:
 * entweder ein weiterer Knoten oder der Abschluss – niemals null.
 * Suche (Strg + F) nach "TODO". Die Platzhalter liefern absichtlich falsche Werte.
 */
public class Knoten extends ListenElement {
   private DatenElement daten;
   private ListenElement nachfolger;

   public Knoten(DatenElement daten) {
      this.daten = daten;
   }

   public DatenElement getDaten() {
      return daten;
   }

   public ListenElement getNachfolger() {
      return nachfolger;
   }

   public void setNachfolger(ListenElement nachfolger) {
      this.nachfolger = nachfolger;
   }

   public int laenge() {
      return 0;       // TODO 3a (Aufgabe 3): Platzhalter ersetzen (ohne if!)
   }

   public boolean enthaelt(DatenElement d) {
      return false;   // TODO 3b (Aufgabe 3): Platzhalter ersetzen
   }

   public ListenElement add(DatenElement d) {
      return this;    // TODO 4b (Aufgabe 4): Rest der Liste erweitern
   }

   public ListenElement entfernen(DatenElement d) {
      return this;    // TODO 5 (Aufgabe 5)
   }

   // Beispiel: kein if mehr nötig – der Abschluss gibt einfach nichts aus.
   public void ausgeben() {
      println("  " + daten.gibSchluesselwert());
      nachfolger.ausgeben();
   }

   // Hilfsmethode für die Tests: alle Schlüsselwerte ab hier, durch Komma getrennt.
   public String alsText() {
      String rest = nachfolger.alsText();
      if (rest.equals("")) {
         return daten.gibSchluesselwert();
      } else {
         return daten.gibSchluesselwert() + ", " + rest;
      }
   }
}

/**
 * Der Abschluss steht immer am Ende der Liste – auch in der leeren Liste.
 * Er hat weder Daten noch einen Nachfolger.
 * Suche (Strg + F) nach "TODO". Die Platzhalter liefern absichtlich falsche Werte.
 */
public class Abschluss extends ListenElement {

   public int laenge() {
      return -1;      // TODO 3a (Aufgabe 3): Platzhalter ersetzen
   }

   public boolean enthaelt(DatenElement d) {
      return true;    // TODO 3b (Aufgabe 3): Platzhalter ersetzen
   }

   public ListenElement add(DatenElement d) {
      return this;    // TODO 4a (Aufgabe 4): neuen Knoten erzeugen und zurückgeben
   }

   public ListenElement entfernen(DatenElement d) {
      return this;    // TODO 5 (Aufgabe 5): Stimmt das schon? Begründe!
   }

   public void ausgeben() {
      // Am Ende gibt es nichts mehr auszugeben.
   }

   public String alsText() {
      return "";
   }
}

/**
 * Der Vertrag für alles, was in einer Liste oder Warteschlange stehen darf.
 */
public interface DatenElement {
   String gibSchluesselwert();

   boolean istGleich(DatenElement d);   // inhaltlich gleich (nicht: dasselbe Objekt)
}

/**
 * Ein Taxi der Taxizentrale.
 */
public class Taxi implements DatenElement {
   private int nummer;
   private String fahrer;

   public Taxi(int nummer, String fahrer) {
      this.nummer = nummer;
      this.fahrer = fahrer;
   }

   public int getNummer() {
      return nummer;
   }

   public String getFahrer() {
      return fahrer;
   }

   public String gibSchluesselwert() {
      return "Taxi " + nummer;
   }

   public boolean istGleich(DatenElement d) {
      return gibSchluesselwert().equals(d.gibSchluesselwert());
   }
}

/**
 * Selbsttest der Kompositum-Liste. Bitte nicht verändern!
 * Starten: Klick auf das kleine Dreieck links neben "@Test"
 * (ganz oben: alle Tests) oder auf der Website "Tests starten".
 */
public class ListeTest {

   private Knoten kette() {
      // k1 (Taxi 12) -> k2 (Taxi 7) -> k3 (Taxi 3) -> Abschluss, ohne add gebaut
      Knoten k1 = new Knoten(new Taxi(12, "Stefan"));
      Knoten k2 = new Knoten(new Taxi(7, "Aylin"));
      Knoten k3 = new Knoten(new Taxi(3, "Jonas"));
      k1.setNachfolger(k2);
      k2.setNachfolger(k3);
      k3.setNachfolger(new Abschluss());
      return k1;
   }

   private Liste dreiTaxis() {
      Liste l = new Liste();
      l.add(new Taxi(12, "Stefan"));
      l.add(new Taxi(7, "Aylin"));
      l.add(new Taxi(3, "Jonas"));
      return l;
   }

   @Test
   public void laengeAbschluss() {
      Assertions.assertEquals(0, new Abschluss().laenge(), "Abschluss.laenge(): Ab dem Abschluss gibt es keine Knoten mehr.");
   }

   @Test
   public void laengeKnotenkette() {
      Assertions.assertEquals(3, kette().laenge(), "Knoten.laenge(): Drei Knoten vor dem Abschluss ergeben 3.");
   }

   @Test
   public void enthaeltAbschluss() {
      Assertions.assertFalse(new Abschluss().enthaelt(new Taxi(7, "Aylin")), "Abschluss.enthaelt(): Im Abschluss ist nichts enthalten.");
   }

   @Test
   public void enthaeltKnotenkette() {
      Assertions.assertTrue(kette().enthaelt(new Taxi(3, "Jonas")), "Knoten.enthaelt(): Taxi 3 steht im letzten Knoten und muss gefunden werden.");
      Assertions.assertFalse(kette().enthaelt(new Taxi(99, "Zoe")), "Knoten.enthaelt(): Taxi 99 gibt es nicht.");
   }

   @Test
   public void addAbschlussLiefertNeuenKnoten() {
      ListenElement e = new Abschluss().add(new Taxi(12, "Stefan"));
      Assertions.assertTrue(e instanceof Knoten, "Abschluss.add() muss einen neuen Knoten zurückgeben.");
      Assertions.assertEquals("Taxi 12", e.alsText(), "Der neue Knoten muss Taxi 12 tragen und vor dem Abschluss stehen.");
   }

   @Test
   public void addKnotenLiefertSichSelbst() {
      Knoten k = kette();
      ListenElement e = k.add(new Taxi(21, "Mira"));
      Assertions.assertTrue(e == k, "Knoten.add() muss sich selbst (this) zurückgeben.");
      Assertions.assertEquals("Taxi 12, Taxi 7, Taxi 3, Taxi 21", k.alsText(), "Knoten.add() muss hinten anhängen.");
   }

   @Test
   public void addListe() {
      Assertions.assertEquals("Taxi 12, Taxi 7, Taxi 3", dreiTaxis().alsText(), "Liste.add(): Die Taxis müssen in der Reihenfolge des Hinzufügens stehen.");
   }

   @Test
   public void entfernenMitte() {
      Liste l = dreiTaxis();
      Assertions.assertTrue(l.entfernen(new Taxi(7, "Aylin")), "entfernen() muss true liefern, wenn Taxi 7 gefunden wurde.");
      Assertions.assertEquals("Taxi 12, Taxi 3", l.alsText(), "Nach entfernen(Taxi 7) bleiben Taxi 12 und Taxi 3.");
   }

   @Test
   public void entfernenErstes() {
      Liste l = dreiTaxis();
      l.entfernen(new Taxi(12, "Stefan"));
      Assertions.assertEquals("Taxi 7, Taxi 3", l.alsText(), "Auch der erste Knoten muss entfernt werden können.");
   }

   @Test
   public void entfernenLetztes() {
      Liste l = dreiTaxis();
      l.entfernen(new Taxi(3, "Jonas"));
      Assertions.assertEquals("Taxi 12, Taxi 7", l.alsText(), "Auch der letzte Knoten muss entfernt werden können.");
   }

   @Test
   public void entfernenNichtVorhanden() {
      Liste l = dreiTaxis();
      Assertions.assertFalse(l.entfernen(new Taxi(99, "Zoe")), "entfernen() muss false liefern, wenn nichts gefunden wird.");
      Assertions.assertEquals("Taxi 12, Taxi 7, Taxi 3", l.alsText(), "Die Liste darf sich dann nicht verändern.");
   }
}
